"""Shared filesystem, diagnostics and serialization utilities."""
import datetime
import errno
import json
import os
import re
import sys

VERSION = '0.5.0-alpha.1'
LEVELS = {'off': 100, 'error': 40, 'warn': 30, 'warning': 30, 'info': 20, 'debug': 10, 'trace': 0}


def log(level, target, message):
    threshold = 20
    settings = os.environ.get('RUST_LOG', '')
    for setting in settings.split(','):
        if '=' in setting:
            prefix, value = setting.split('=', 1)
            if target.startswith(prefix):
                threshold = LEVELS.get(value.lower(), 20)
        elif setting:
            threshold = LEVELS.get(setting.lower(), 20)
    if LEVELS.get(level.lower(), 20) < threshold:
        return
    date = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    sys.stderr.write(f'{date} [{level.upper()}] ({target}): {message}\n')
    sys.stderr.flush()


class BookError(Exception):
    def __init__(self, *messages):
        self.messages = [str(m) for m in messages]
        super().__init__(self.messages[0] if self.messages else '')


def report(error):
    messages = error.messages if isinstance(error, BookError) else [str(error)]
    for i, message in enumerate(messages):
        log('ERROR', 'mdbook_core::utils', ('Error: ' if i == 0 else '\tCaused By: ') + message)


def os_error(e):
    if isinstance(e, UnicodeError):
        return 'stream did not contain valid UTF-8'
    number = getattr(e, 'errno', None) or 2
    return f'{os.strerror(number)} (os error {number})'


def quote(s):
    return json.dumps(str(s), ensure_ascii=False)


def escape(s):
    return str(s).replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;').replace("'", '&#x27;')


def text_escape(s):
    return str(s).replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')


def write(path, value):
    path = os.fspath(path)
    os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
    mode = 'wb' if isinstance(value, bytes) else 'w'
    kw = {} if isinstance(value, bytes) else {'encoding': 'utf-8', 'newline': ''}
    with open(path, mode, **kw) as file:
        file.write(value)


def read(path):
    with open(path, encoding='utf-8', newline='') as f:
        return f.read()


def html_path(path):
    return os.path.splitext(path)[0] + '.html'


def path_join(a, b):
    return os.path.join(os.fspath(a), os.fspath(b))


def iter_chapters(book):
    sections = book['sections'] if isinstance(book, dict) else book
    for item in sections:
        if isinstance(item, dict) and 'Chapter' in item:
            ch = item['Chapter']
            yield ch
            yield from iter_chapters(ch.get('sub_items', []))


def public_book(book):
    def clean(x):
        if isinstance(x, dict):
            return {k: clean(v) for k, v in x.items() if not k.startswith('_') or k == '__non_exhaustive'}
        if isinstance(x, list):
            return [clean(v) for v in x]
        return x
    return clean(book)
