"""Small independent TOML reader used if the interpreter has no TOML module.

Supports the scalar, array, dotted-key and table forms used by book configs.
"""
import ast
import json
import re


class TOMLDecodeError(ValueError):
    pass


def parts(s, delimiter=','):
    out, start, level, string, escaped = [], 0, 0, None, False
    i = 0
    while i < len(s):
        c = s[i]
        if string:
            if escaped:
                escaped = False
            elif c == '\\' and string == '"':
                escaped = True
            elif c == string:
                string = None
        elif c in "\"'":
            string = c
        elif c in '[{(':
            level += 1
        elif c in ']})':
            level -= 1
        elif c == delimiter and level == 0:
            out.append(s[start:i].strip()); start = i + 1
        i += 1
    out.append(s[start:].strip())
    return out


def scalar(s):
    s = s.strip()
    if s.startswith(('"""', "'''")):
        q = s[:3]
        if not s.endswith(q): raise TOMLDecodeError('Unterminated string')
        t = s[3:-3]
        if t.startswith('\n'): t = t[1:]
        if q == "'''"): return t
        return re.sub(r'\\(["\\nrtbf])', lambda m: {'n':'\n','r':'\r','t':'\t','b':'\b','f':'\f'}.get(m[1], m[1]), t)
    if s.startswith('"'):
        return json.loads(s)
    if s.startswith("'") and s.endswith("'"):
        return s[1:-1]
    if s == 'true': return True
    if s == 'false': return False
    if s.startswith('[') and s.endswith(']'):
        return [scalar(p) for p in parts(s[1:-1]) if p]
    if s.startswith('{') and s.endswith('}'):
        d = {}
        for p in parts(s[1:-1]):
            if not p: continue
            k, v = p.split('=', 1)
            setkey(d, parts(k, '.'), scalar(v))
        return d
    try:
        t = s.replace('_', '')
        return float(t) if any(c in t for c in '.eE') else int(t, 0 if t.startswith(('0x','0o','0b')) else 10)
    except ValueError:
        raise TOMLDecodeError('Invalid value')


def key(k):
    k = k.strip()
    return scalar(k) if k.startswith(('"', "'")) else k


def setkey(d, keys, value):
    for k in keys[:-1]: d = d.setdefault(key(k), {})
    d[key(keys[-1])] = value


def loads(s):
    root, current = {}, None
    current = root
    statements = []
    buf = ''
    for line in s.splitlines():
        # Strip comments only when outside strings.
        string, escape, content = None, False, ''
        for c in line:
            if string:
                content += c
                if escape: escape = False
                elif c == '\\' and string == '"': escape = True
                elif c == string: string = None
            elif c in "'\"": content += c; string = c
            elif c == '#': break
            else: content += c
        buf += content + '\n'
        if buf.count('"""') % 2 or buf.count("'''") % 2: continue
        # Wait for closing arrays or inline tables.
        stripped = re.sub(r'"(?:\\.|[^"\\])*"|\'[^\']*\'', '', buf)
        if stripped.count('[') > stripped.count(']') or stripped.count('{') > stripped.count('}'):
            continue
        statements.append(buf.strip()); buf = ''
    if buf.strip(): statements.append(buf.strip())
    for statement in statements:
        if not statement: continue
        if statement.startswith('['):
            if not statement.endswith(']'): raise TOMLDecodeError('Unclosed table')
            ks = parts(statement[1:-1], '.')
            current = root
            for k in ks: current = current.setdefault(key(k), {})
        else:
            ps = parts(statement, '=')
            if len(ps) < 2: raise TOMLDecodeError('Expected equals')
            setkey(current, parts(ps[0], '.'), scalar('='.join(ps[1:])))
    return root
PY
