"""Configuration decoding and environment overlays."""
import copy
import json
import os
import re
from common import BookError, log, os_error, read, quote
try:
    import tomllib as toml
except ImportError:
    try:
        import tomli as toml
    except ImportError:
        try:
            from pip._vendor import tomli as toml
        except ImportError:
            import tiny_toml as toml

BOOK_DEFAULTS = {'authors': [], 'language': 'en', 'src': 'src'}
BUILD_DEFAULTS = {'build-dir': 'book', 'create-missing': True, 'extra-watch-dirs': [], 'use-default-preprocessors': True}
SCHEMAS = {
 'book': {'title': 'a string', 'authors': 'a sequence', 'description': 'a string', 'src': 'path string', 'language': 'a string', 'text-direction': 'direction'},
 'build': {'build-dir': 'path string', 'create-missing': 'a boolean', 'use-default-preprocessors': 'a boolean', 'extra-watch-dirs': 'a sequence'},
 'rust': {'edition': 'edition'},
}


def type_name(v):
    if isinstance(v, bool): return 'boolean `' + str(v).lower() + '`'
    if isinstance(v, int): return f'integer `{v}`'
    if isinstance(v, float): return f'floating point `{v}`'
    if isinstance(v, str): return 'string ' + quote(v)
    if isinstance(v, list): return 'sequence'
    return 'map'


def validate(table, data):
    if not isinstance(data, dict):
        raise BookError('Invalid configuration file', f'invalid type: {type_name(data)}, expected struct {table.title()}Config\n')
    out = {}
    for k, v in data.items():
        expect = SCHEMAS[table].get(k)
        if not expect: continue
        bad = False
