from common import BookError, VERSION, iter_chapters, log, os_error, quote, read, write, public_book


def plain_markdown(text):
    text = re.sub(r'!?(\[([^\]]*)\])\([^)]*\)', r'\2', text)
    text = re.sub(r'<[^>]*>', '', text)
    text = re.sub(r'`+([^`]+)`+', r'\1', text)
    text = re.sub(r'\\([!"#$%&\'()*+,\-./:;<=>?@\[\]\\^_`{|}~])', r'\1', text)
    text = re.sub(r'(?<!\w)[*_~]+|[*_~]+(?!\w)', '', text)
    return html.unescape(text)


def extract_link(s, references=None):
    """Parse a link at the front of a summary list item."""
    if not s.startswith('['): return None
    depth, close, escaped = 0, None, False
    for i, c in enumerate(s):
        if escaped: escaped = False; continue
        if c == '\\': escaped = True; continue
        if c == '[': depth += 1
        if c == ']':
            depth -= 1
            if depth == 0: close = i; break
    if close is None: return None
    label, tail = s[1:close], s[close+1:]
    if tail.startswith('('):
        depth, quotechar, escaped, end = 0, None, False, None
        for i, c in enumerate(tail):
            if escaped: escaped = False; continue
            if c == '\\': escaped = True; continue
            if quotechar:
                if c == quotechar: quotechar = None
                continue
            if c in "'\"" and i > 0 and tail[i-1].isspace(): quotechar = c
            elif c == '(': depth += 1
            elif c == ')':
                depth -= 1
                if depth == 0: end = i; break
        if end is None: return None
        target = tail[1:end].strip()
        if target.startswith('<'):
            target = target[1:target.find('>')]
        else:
            target = re.split(r'\s+[\'\"]', target)[0].strip()
        if ' ' in target and not tail[1:end].strip().startswith('<'): return None
        return plain_markdown(label), html.unescape(re.sub(r'\\(.)',r'\1',target)), close+2+end
    refs = references or {}
    if tail.startswith('['):
        e = tail.find(']')
        if e == -1: return None
        key = tail[1:e] or label
    else: key = label
    if key.lower().strip() in refs:
        return plain_markdown(label), refs[key.lower().strip()], close+1
