    sections, stack, counts = [], [], []
    references = {}
    lines = text.splitlines()
    for line in lines:
        match = re.match(r'^ {0,3}\[([^\]]+)\]:\s*(?:<([^>]+)>|(\S+))', line)
        if match: references[match[1].lower().strip()] = html.unescape(match[2] or match[3])
