                        if os.path.islink(os.path.join(directory,d)):size+=os.lstat(os.path.join(directory,d)).st_size;count+=1
                shutil.rmtree(destination)
        except OSError as e:raise BookError('Unable to remove the book',os_error(e))
    if count:
        units=['B','KiB','MiB','GiB','TiB'];unit=0;number=float(size)
        while number>=1024 and unit<len(units)-1:number/=1024;unit+=1
        human=str(size)+'B' if unit==0 else f'{number:.2f}{units[unit]}'
        print(f'Removed {count} '+('file' if count==1 else 'files')+', '+human+' total')
    else:print('Removed 0 files')


def run_backend(name,root,config,book,destination,serve=False):
    if name=='markdown':
        for ch in iter_chapters(book):
            if ch.get('path'):
                path=os.path.join(destination,ch['path']);log('DEBUG','mdbook_core::utils::fs',f'Creating {path}');write(path,ch['content'])
        return
    if name=='html':
        HTMLBook(root,config,book,destination,serve).render();return
    target='mdbook_driver::builtin_renderers'
    log('INFO',target,f'Invoking the {quote(name)} renderer')
    options=config.get('output',{}).get(name,{}) or {}
    command=options.get('command','mdbook-'+name)
    try:args=shlex.split(command)
    except ValueError:args=command.split()
    context={'version':VERSION,'root':root,'book':public_book(book),'config':config,'destination':destination}
    try:
        result=subprocess.run(args,input=json.dumps(context,ensure_ascii=False,separators=(',',':')).encode())
    except (OSError,IndexError) as e:
        if options.get('optional',False):
            log('WARN',target,f'The command `{command}` for backend `{name}` was not found, but was marked as optional.');return
        log('ERROR',target,f'The command `{command}` wasn\'t found, is the {quote(name)} backend installed? If you want to ignore this error when the {quote(name)} backend is not installed, set `optional = true` in the `[output.{name}]` section of the book.toml configuration file.')
        raise BookError('Rendering failed','Unable to start the backend',os_error(e))
    if result.returncode:
        log('ERROR',target,'Renderer exited with non-zero return code.')
        raise BookError('Rendering failed',f'The {quote(name)} renderer failed')


def build(root,config,book,destination,order,serve=False):
    log('INFO','mdbook_driver::mdbook','Book building has started')
    renderers=sorted(config.get('output',{})) or ['html']
    for name in renderers:
        prepared=preprocess(book,root,config,name,order)
        dest=os.path.join(destination,name) if len(renderers)>1 else destination
        log('INFO','mdbook_driver::mdbook',f'Running the {name} backend')
        run_backend(name,root,config,prepared,dest,serve)


def test(root,config,book,options,order):
    prepared=preprocess(book,root,config,'test',order)
    chapters=[ch for ch in iter_chapters(prepared) if ch.get('source_path')]
    name=options.get('chapter')
    if name is not None:
        chapters=[ch for ch in chapters if name in [ch['name'],ch.get('source_path'),ch.get('path')]]
        if not chapters:raise BookError('Chapter not found: '+name)
    failed=False
    for ch in chapters:
        log('INFO','mdbook_driver::mdbook',f"Testing chapter '{ch['name']}': {quote(ch['source_path'])}")
        with tempfile.TemporaryDirectory(prefix='mdbook-test-') as temp:
            path=ch['source_path'];write(os.path.join(temp,path),ch['content'])
            args=['rustdoc','--test',path]
            edition=config.get('rust',{}).get('edition')
            if edition:args+=['--edition',edition]
            for library in options.get('library-path',[]):args+=['-L',os.path.abspath(library)]
            try:r=subprocess.run(args,cwd=temp,capture_output=True,text=True)
            except OSError as e:raise BookError('Could not run rustdoc',os_error(e))
            if r.returncode:
                failed=True
                log('ERROR','mdbook_driver::mdbook','rustdoc returned an error:\n\n--- stdout\n'+r.stdout+'\n--- stderr\n'+r.stderr)
    if failed:raise BookError('One or more tests failed')


def open_book(destination):
    import webbrowser
    file=os.path.join(destination,'index.html')
    try:webbrowser.open('file://'+file)
    except Exception:pass


def watch(root,config,book,destination,order,options,serve=False):
    build(root,config,book,destination,order,serve)
    if options.get('open'):open_book(destination)
    if serve:
        import http.server
        import threading
        from functools import partial
        host=options.get('hostname','localhost');port=options.get('port','3000')
        try:port=int(port)
        except ValueError:raise BookError('Invalid port: '+str(port))
        class Handler(http.server.SimpleHTTPRequestHandler):
            def log_message(self,*args):pass
            def send_error(self,code,message=None,explain=None):
                if code==404 and os.path.exists(os.path.join(destination,'404.html')):
                    data=open(os.path.join(destination,'404.html'),'rb').read();self.send_response(404);self.send_header('Content-Type','text/html');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
                else:super().send_error(code,message,explain)
        try:server=http.server.ThreadingHTTPServer((host,port),partial(Handler,directory=destination))
        except OSError as e:raise BookError('Unable to serve the book',os_error(e))
        threading.Thread(target=server.serve_forever,daemon=True).start()
        log('INFO','mdbook::cmd::serve',f'Serving on: http://{host}:{port}')
    log('INFO','mdbook::cmd::watch','Listening for changes...')
    def stamp():
        paths=[os.path.join(root,'book.toml'),os.path.join(root,config['book'].get('src','src')),os.path.join(root,'theme')]+[os.path.join(root,d) for d in config.get('build',{}).get('extra-watch-dirs',[])]
        stat={}
        for path in paths:
            if os.path.isfile(path):stat[path]=os.stat(path).st_mtime_ns
            for d,ds,fs in os.walk(path):
                for f in fs:
                    p=os.path.join(d,f)
                    try:stat[p]=os.stat(p).st_mtime_ns
                    except OSError:pass
        return stat
    old=stamp()
    try:
        while True:
            time.sleep(1);new=stamp()
            if new!=old:
                try:
                    config=configuration.load(root);book=load_book(root,config);order=pipeline_order(config)
                    build(root,config,book,destination,order,serve)
                except BookError as e:report(e)
                old=stamp()
    except KeyboardInterrupt:return


def main(argv=None):
    global PROG
    if not sys.argv[0].endswith(('.py','.pyz')):PROG=os.path.basename(sys.argv[0])
    argv=sys.argv[1:] if argv is None else argv
    try:
        command,options,args=parse(argv)
        if command=='completions':sys.stdout.write(output_data.text('completion:'+args[0]));return 0
        root=os.path.abspath(args[0]) if args else os.getcwd()
        if command=='init':initialize(root,options);return 0
        config=configuration.load(root)
        if 'dest-dir' in options:
            config['build']=dict(configuration.BUILD_DEFAULTS,**config.get('build',{}));config['build']['build-dir']=options['dest-dir']
        book=load_book(root,config)
        order=pipeline_order(config)
        destination=os.path.join(root,config.get('build',{}).get('build-dir','book'))
        if command=='clean':clean(destination)
        elif command=='test':test(root,config,book,options,order)
        elif command in ['watch','serve']:watch(root,config,book,destination,order,options,command=='serve')
        else:
            build(root,config,book,destination,order)
            if options.get('open'):open_book(destination)
        return 0
    except BookError as e:report(e);return 101
    except (OSError,UnicodeError) as e:report(BookError(os_error(e)));return 101
    except BrokenPipeError:return 101


if __name__=='__main__':sys.exit(main())
